WHERE c.champion<>o.opponent
ON CONFLICT(lane,champion,opponent) DO NOTHING;
DO $verify$
BEGIN
IF (SELECT count(*) FROM pickou.champions)<>173 OR (SELECT count(*) FROM pickou.champion_lanes)<>266 OR (SELECT count(*) FROM pickou.matchups)<>14468 THEN
RAISE EXCEPTION 'PICKOU roster counts do not match expected 173/266/14468';
END IF;
IF EXISTS(SELECT 1 FROM pickou.champion_lanes l WHERE NOT EXISTS(SELECT 1 FROM pickou.champions c WHERE c.name=l.champion)) THEN RAISE EXCEPTION 'Missing champion foreign key'; END IF;
END $verify$;
